import { app, BrowserWindow, protocol, screen, type WebContentsView } from 'electron';
import assert from 'node:assert/strict';
import { join } from 'node:path';
import { readFileSync, writeFileSync } from 'node:fs';
import { createServer } from 'node:http';
import { PanelHost } from '../../src/desktop/panels.js';
import { projectDirectory } from '../../src/core/paths.js';
import type { AppSnapshot } from '../../src/shared/types.js';
import type { PanelSnapshot } from '../../src/shared/panels.js';
const root=process.argv[2];
protocol.registerSchemesAsPrivileged([{scheme:'mixcat-preview',privileges:{standard:true,secure:true,supportFetchAPI:true,stream:true}}]);
for(const name of ['userData','sessionData','logs','crashDumps','temp'] as const) app.setPath(name,projectDirectory(root,name));
let window:BrowserWindow|undefined, host:PanelHost|undefined, snapshot:PanelSnapshot, downloads:string[]=[], events:unknown[]=[];
const delay=(ms:number)=>new Promise(done=>setTimeout(done,ms));
app.whenReady().then(async()=>{
  window=new BrowserWindow({show:true,alwaysOnTop:process.platform==='win32',width:900,height:700,webPreferences:{sandbox:true,contextIsolation:true,nodeIntegration:false}});
  await window.loadURL('data:text/html,<title>Panel media proof</title>');
  window.on('resize',()=>events.push({type:'resize',at:Date.now(),bounds:window!.getBounds()}));
  const canPlay=await window.webContents.executeJavaScript(`document.createElement('video').canPlayType('video/mp4; codecs="avc1.42E01E"')`);
  host=new PanelHost(window,state=>{snapshot=state;});
  host.observe({projects:[{id:'p',root}],selected:{project:{id:'p',root},nodes:[{id:'n'}]}} as AppSnapshot);
  const bound=await host.command({type:'bind',projectId:'p',nodeId:'n'});
  snapshot=await host.command({type:'open',projectId:'p',nodeId:'n',target:{type:'file',path:join(root,'preview.mp4')}});
  const view=window.contentView.children.find(child=>'webContents' in child && (child as WebContentsView).webContents!==window!.webContents) as WebContentsView;
  const setVisible=view.setVisible.bind(view);view.setVisible=value=>{events.push({type:'setVisible',value,at:Date.now()});setVisible(value);};
  view.webContents.session.on('will-download',(_e,item)=>downloads.push(item.getMimeType()));
  await host.command({type:'layout',projectId:'p',nodeId:'n',generation:bound.generation!,bounds:{x:0,y:0,width:900,height:650}});
  for(let n=0;n<60 && snapshot.panels[0].loading;n++)await delay(50);
  const response=await view.webContents.session.fetch(view.webContents.getURL());
  writeFileSync(join(root,'navigation.json'),JSON.stringify({canPlay,downloads,error:snapshot.panels[0].error,status:response.status,contentType:response.headers.get('content-type'),disposition:response.headers.get('content-disposition'),range:response.headers.get('accept-ranges')},null,2));
  assert.equal(snapshot.panels[0].error,undefined,'supported output must open without becoming a download');
  let media:any;
  for(let n=0;n<60;n++){media=await view.webContents.executeJavaScript(`(()=>{const v=document.querySelector('video');return v&&{ready:v.readyState,width:v.videoWidth,height:v.videoHeight,error:v.error?.code};})()`);if(media?.ready>=1)break;await delay(50);}
  assert.equal(media?.width,32);assert.equal(media?.height,32);
  await view.webContents.executeJavaScript(`(()=>{window.mediaEvents=[];const v=document.querySelector('video');for(const type of ['play','playing','pause','suspend','waiting','stalled','timeupdate','loadstart','emptied'])v.addEventListener(type,()=>mediaEvents.push({type,at:Date.now(),time:v.currentTime,paused:v.paused,hidden:document.hidden}));document.addEventListener('visibilitychange',()=>mediaEvents.push({type:'visibility',at:Date.now(),hidden:document.hidden}));return true;})()`);
  await host.command({type:'layout',projectId:'p',nodeId:'n',generation:bound.generation!,bounds:null});
  await host.command({type:'layout',projectId:'p',nodeId:'n',generation:bound.generation!,bounds:{x:0,y:0,width:900,height:650}});
  await delay(50);
  writeFileSync(join(root,'visibility.json'),JSON.stringify({parent:{visible:window.isVisible(),minimized:window.isMinimized(),offscreen:window.webContents.isOffscreen(),bounds:window.getBounds(),document:await window.webContents.executeJavaScript('document.visibilityState')},native:{visible:view.getVisible(),attached:window.contentView.children.includes(view),bounds:view.getBounds(),offscreen:view.webContents.isOffscreen(),document:await view.webContents.executeJavaScript('document.visibilityState')},displays:screen.getAllDisplays().map(display=>({bounds:display.bounds,workArea:display.workArea}))},null,2));
  await view.webContents.executeJavaScript(`(()=>{const v=document.querySelector('video');v.muted=true;return v.play().then(()=>true);})()`,true);await delay(300);
  const playback=await view.webContents.executeJavaScript(`(()=>{const v=document.querySelector('video');return {time:v.currentTime,duration:v.duration,paused:v.paused,ended:v.ended,ready:v.readyState,error:v.error?.code,hidden:document.hidden}})()`);
  writeFileSync(join(root,'playback.json'),JSON.stringify({...playback,nativeVisible:view.getVisible(),events,mediaEvents:await view.webContents.executeJavaScript('mediaEvents')},null,2));const time=playback.time;
  const markup=(await response.text()).replace(/src="[^"]+"/,'src="/clip.mp4"'), clip=readFileSync(join(root,'preview.mp4')), csp=response.headers.get('content-security-policy')!;
  const server=createServer((req,res)=>{res.writeHead(200,{'Content-Type':req.url==='/clip.mp4'?'video/mp4':'text/html; charset=utf-8','Content-Security-Policy':csp,'X-Content-Type-Options':'nosniff'});res.end(req.url==='/clip.mp4'?clip:markup);});await new Promise<void>(done=>server.listen(0,'127.0.0.1',done));
  await host.command({type:'layout',projectId:'p',nodeId:'n',generation:bound.generation!,bounds:null});
  const comparison=new (await import('electron')).WebContentsView({webPreferences:{session:view.webContents.session,contextIsolation:true,nodeIntegration:false,sandbox:true,webSecurity:true,spellcheck:false}});comparison.setVisible(false);window.contentView.addChildView(comparison);comparison.setBounds(view.getBounds());const navigation=comparison.webContents.loadURL(`http://127.0.0.1:${(server.address() as any).port}/`);comparison.setVisible(true);await navigation;
  for(let n=0;n<60 && !await comparison.webContents.executeJavaScript('document.querySelector("video")?.readyState>=1');n++)await delay(50);
  await comparison.webContents.executeJavaScript(`(()=>{const v=document.querySelector('video');v.muted=true;return v.play().then(()=>true);})()`,true);await delay(300);
  const httpPlayback=await comparison.webContents.executeJavaScript(`(()=>{const v=document.querySelector('video');return {time:v.currentTime,duration:v.duration,paused:v.paused,ready:v.readyState,width:v.videoWidth,height:v.videoHeight,hidden:document.hidden}})()`);
  writeFileSync(join(root,'same-markup-ab.json'),JSON.stringify({guarded:playback,http:httpPlayback,sameSession:true,sameCsp:true,samePlayCall:true,sourceBytes:clip.length},null,2));comparison.webContents.close();server.closeAllConnections();await new Promise<void>(done=>server.close(()=>done()));
  assert(time>0.1);
  writeFileSync(join(root,'evidence.json'),JSON.stringify({passed:true,media,currentTime:time,downloads},null,2));
  host.close();window.destroy();app.quit();
}).catch(error=>{console.error(error);host?.close();window?.destroy();app.exit(1);});
